{
  "schemaId": "builtin:openpipeline.logs.pipelines",
  "pipeline (customId)": "<SIFT_OPENPIPELINE_PIPELINE>",
  "add": {
    "metricExtraction": {
      "processors": [
        {
          "id": "sift-<proposal id>-metric",
          "type": "counterMetric",
          "matcher": "matchesValue(service.name, \"inventory\") and matchesPhrase(content, \"heartbeat ok\")",
          "description": "Sift · count inventory heartbeats",
          "enabled": true,
          "counterMetric": {
            "metricKey": "log.inventory.heartbeat.count",
            "dimensions": [
              {
                "extractionType": "field",
                "sourceFieldName": "k8s.pod.name",
                "destinationFieldName": "k8s.pod.name"
              }
            ]
          }
        }
      ]
    },
    "storage": {
      "processors": [
        {
          "id": "sift-<proposal id>-storage",
          "type": "noStorage",
          "matcher": "matchesValue(service.name, \"inventory\") and matchesPhrase(content, \"heartbeat ok\")",
          "description": "Sift · do not store heartbeat lines",
          "enabled": true
        }
      ]
    }
  }
}

{
  "schemaId": "builtin:openpipeline.metrics.pipelines",
  "pipeline (customId)": "<SIFT_OPENPIPELINE_PIPELINE>",
  "add": {
    "processing": {
      "processors": [
        {
          "id": "sift-<proposal id>",
          "type": "fieldsRemove",
          "matcher": "metric.key == \"http.server.request.duration\"",
          "description": "Sift · Remove user.id from http.server.request.duration",
          "enabled": true,
          "fieldsRemove": {
            "fields": [
              "user.id"
            ]
          }
        }
      ]
    }
  }
}

{
  "schemaId": "builtin:openpipeline.spans.pipelines",
  "pipeline (customId)": "<SIFT_OPENPIPELINE_PIPELINE>",
  "add": {
    "processing": {
      "processors": [
        {
          "id": "sift-<proposal id>",
          "type": "fieldsRemove",
          "matcher": "matchesValue(service.name, \"inventory\") and span.name == \"SELECT inventory.stock\"",
          "description": "Sift · Remove db.statement from inventory SELECT spans",
          "enabled": true,
          "fieldsRemove": {
            "fields": [
              "db.statement"
            ]
          }
        }
      ]
    }
  }
}

{
  "schemaId": "builtin:openpipeline.spans.pipelines",
  "pipeline (customId)": "<SIFT_OPENPIPELINE_PIPELINE>",
  "add": {
    "processing": {
      "processors": [
        {
          "id": "sift-<proposal id>",
          "type": "drop",
          "matcher": "matchesValue(service.name, \"frontend\") and matchesValue(url.path, \"/static/*\")",
          "description": "Sift · Drop static asset spans from frontend",
          "enabled": true
        }
      ]
    }
  }
}
